import type { IngredientResolution } from '@motivation/shared';

/**
 * Story 319 — several library rows share this ingredient's canonical name and
 * they disagree about calories, so the bound row was picked on how often it
 * was logged, which says nothing about which one is right. Show the spread
 * rather than resolve it silently; null when the siblings agree (or there are
 * none), which is the common case.
 */
export function createDivergenceBadge(resolution: Pick<IngredientResolution, 'divergence'>): HTMLSpanElement | null {
    const { divergence } = resolution;
    if (!divergence) return null;
    const badge = document.createElement('span');
    badge.className = 'provenance-badge divergence-badge';
    badge.textContent = `⚠ ${Math.round(divergence.kcal_min)}–${Math.round(divergence.kcal_max)} kcal/100g`;
    // Not "…and disagree": a sibling with no comparable kcal still shares the
    // name and is counted here, while the range beside it covers only the rows
    // that could be compared.
    badge.title = `${divergence.sibling_count} library rows share this name — the most-logged one was used.`;
    return badge;
}
